sys_script.script:
(function executeRule(current, previous) {

    // Prüfung direkt im Script – nicht über Condition-Feld
    // weil bei Delete 'current' anders ausgewertet wird

    var isOwner = current.getValue('u_is_owner');

    // Boolean-Wert sicher prüfen (kann '1', 'true' oder true sein)
    if (isOwner !== '1' && isOwner !== true && isOwner !== 'true') {
        return; // Kein Owner → nichts tun
    }

    // Ab hier: es ist ein Owner-Eintrag → blockieren

    if (current.operation() === 'delete') {
        current.setAbortAction(true);
        gs.addErrorMessage('Der Ersteller des Antrags kann nicht entfernt werden.');
        return;
    }

    if (current.operation() === 'update') {
        var newState  = current.getValue('u_state');
        var prevState = previous.getValue('u_state');

        if (newState === 'revoked' && prevState !== 'revoked') {
            current.setAbortAction(true);
            gs.addErrorMessage('Der Ersteller des Antrags kann nicht entfernt werden.');
            return;
        }

        // is_owner darf nicht auf false gesetzt werden
        current.u_is_owner = true;
    }

})(current, previous);
